<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$jobs=db()->query("SELECT j.*,c.name company FROM jobs j JOIN companies c ON c.id=j.company_id WHERE j.status='Open' ORDER BY j.deadline");$skills=db()->query('SELECT s.name,ss.level,ss.verified FROM student_skills ss JOIN skills s ON s.id=ss.skill_id JOIN students st ON st.id=ss.student_id WHERE st.user_id='.(int)actor_id());page_top('Career Center');?><div class='row g-4'><div class='col-lg-5'><div class='card p-4'><h5>Skill Profile</h5><?php foreach($skills as $s):?><div class='mb-3'><div class='d-flex justify-content-between'><span><?=e($s['name'])?></span><span><?=e($s['level'])?>/10</span></div><div class='progress'><div class='progress-bar' style='width:<?=min(100,(int)$s['level']*10)?>%'></div></div></div><?php endforeach;?></div></div><div class='col-lg-7'><div class='card p-4'><h5>Open Opportunities</h5><?php foreach($jobs as $j):?><div class='border-bottom py-3'><strong><?=e($j['title'])?></strong> · <?=e($j['company'])?><div class='small text-muted'><?=e($j['location'])?> · ₹<?=e(number_format($j['package_amount']))?> · Deadline <?=e($j['deadline'])?></div></div><?php endforeach;?></div></div></div><?php page_bottom(); ?>